<?php $types=['addendum'=>'ملحق عقد','additional_work'=>'أعمال إضافية','deduction'=>'خصم','commercial_adjustment'=>'تسوية تجارية'];$effects=['increase'=>'زيادة','decrease'=>'تخفيض','none'=>'غير مالي'];$statuses=['draft'=>'مسودة','approved'=>'معتمد','cancelled'=>'ملغي'];?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?=e($variation['variation_code'])?></div><h2 class="page-title"><?=e($variation['title'])?></h2></div><div class="col-auto d-flex gap-2"><a class="btn" href="/contracts/<?=(int)$variation['client_contract_id']?>/variations">العودة للقائمة</a><?php if($canEdit):?><a class="btn" href="/contract-variations/<?=(int)$variation['id']?>/edit">تعديل</a><?php endif;?><?php if($canApprove&&$variation['status']==='draft'):?><form method="post" action="/contract-variations/<?=(int)$variation['id']?>/approve" class="js-confirm-form" data-confirm="سيتم اعتماد الملحق وقفل بياناته التجارية."><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">اعتماد</button></form><?php endif;?><?php if($canCancel&&in_array($variation['status'],['draft','approved'],true)):?><form method="post" action="/contract-variations/<?=(int)$variation['id']?>/cancel" class="js-confirm-form" data-confirm="سيتم إلغاء الملحق مع الاحتفاظ بسجل التدقيق."><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-danger">إلغاء الملحق</button></form><?php endif;?></div></div></div>
<div class="card"><div class="card-body"><div class="row g-4"><?php foreach(['العقد'=>$variation['contract_code'].' - '.$variation['contract_title'],'المشروع'=>$variation['project_code'].' - '.$variation['project_name'],'الرقم المرجعي'=>$variation['variation_number']?:'—','النوع'=>$types[$variation['variation_type']]??$variation['variation_type'],'تاريخ الملحق'=>$variation['variation_date'],'تاريخ السريان'=>$variation['effective_date']?:'—','المبلغ'=>$variation['amount']??'—','الاتجاه'=>$effects[$variation['amount_effect']]??$variation['amount_effect'],'نسبة الزيادة'=>$variation['markup_percentage']??'—','الحالة'=>$statuses[$variation['status']]??$variation['status']] as $label=>$value):?><div class="col-md-4"><div class="text-secondary small"><?=$label?></div><div class="fw-bold"><?=e((string)$value)?></div></div><?php endforeach;?></div><?php if($variation['approved_at']):?><hr><div class="text-secondary">اعتمد بواسطة <?=e($variation['approved_by_name']??'—')?> في <?=e($variation['approved_at'])?></div><?php endif;?><?php if($variation['cancelled_at']):?><div class="text-secondary">ألغي بواسطة <?=e($variation['cancelled_by_name']??'—')?> في <?=e($variation['cancelled_at'])?></div><?php endif;?><?php foreach(['الوصف'=>'description','الملاحظات'=>'notes'] as $label=>$key):if(!$variation[$key])continue;?><hr><h4><?=$label?></h4><div><?=nl2br(e($variation[$key]))?></div><?php endforeach;?></div></div>
